// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(uint256 _val) public {
        bool ok;
        try c.SetMinSum(_val) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(c.MinSum() == _val);
        } else {
            assertTrue(ok);
        }
    }
}
